<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class Imports {
    public const HEADERS=['full_name','official_email','organisation_id','profession_id','position_id','grade_id','employment_status_id','facility_id','unit_id'];
    public static function read(string $file,string $ext,array $mapping=[]):array {
        if(filesize($file)>5*1024*1024)throw new \InvalidArgumentException('Fail import maksimum 5 MB.');
        if($ext==='csv'){$h=fopen($file,'r');if(!$h)throw new \RuntimeException('Fail tidak tersedia.');try{$rows=[];while(($r=fgetcsv($h,65536,',','"',''))!==false){if($r===[null])continue;if(count($r)>count(self::HEADERS)||count($rows)>1000)throw new \InvalidArgumentException('Had import: 1000 baris, 9 lajur.');foreach($r as $v)if(!mb_check_encoding((string)$v,'UTF-8')||mb_strlen((string)$v)>2000)throw new \InvalidArgumentException('Gunakan CSV UTF-8 dan nilai ringkas.');$rows[]=$r;}}finally{fclose($h);}}
        elseif($ext==='xlsx')$rows=self::xlsx($file);else throw new \InvalidArgumentException('Gunakan CSV UTF-8 atau XLSX tanpa formula; XLS tidak disokong.');
        if(count($rows)<2)throw new \InvalidArgumentException('Import memerlukan header dan sekurang-kurangnya satu staf.');$head=array_shift($rows);if($mapping){foreach($mapping as $from=>$to)if(!is_string($from)||!in_array($to,self::HEADERS,true))throw new \InvalidArgumentException('Column mapping tidak sah.');$head=array_map(static fn($column)=>$mapping[$column]??$column,$head);}$head[0]=ltrim((string)($head[0]??''),"\xef\xbb\xbf");if(count($head)!==count(array_unique($head))||array_diff($head,self::HEADERS)||!in_array('full_name',$head,true)||!in_array('official_email',$head,true)||!in_array('organisation_id',$head,true))throw new \InvalidArgumentException('Header tidak sah. Rujuk template import.');$out=[];foreach($rows as $r){if(count($r)>count($head))throw new \InvalidArgumentException('Bilangan lajur tidak sepadan.');$out[]=array_combine($head,array_pad($r,count($head),''));}return $out;
    }
    private static function xml(string $v): \SimpleXMLElement {
        if(strlen($v)>10*1024*1024||preg_match('/<!DOCTYPE|<!ENTITY|\x00/i',$v))throw new \InvalidArgumentException('XML tidak selamat.');$old=libxml_use_internal_errors(true);try{$x=simplexml_load_string($v,'SimpleXMLElement',LIBXML_NONET);if(!$x)throw new \InvalidArgumentException('XLSX tidak sah.');return $x;}finally{libxml_clear_errors();libxml_use_internal_errors($old);}
    }
    private static function xlsx(string $file):array {
        if(!class_exists('ZipArchive')||!extension_loaded('simplexml'))throw new \RuntimeException('XLSX memerlukan extension zip dan SimpleXML; gunakan CSV sementara.');$z=new \ZipArchive();if($z->open($file)!==true)throw new \InvalidArgumentException('XLSX tidak sah.');
        try{if($z->numFiles>200)throw new \InvalidArgumentException('Arkib terlalu besar.');$total=0;for($i=0;$i<$z->numFiles;$i++){$s=$z->statIndex($i);$total+=$s['size'];if($total>30*1024*1024||$s['size']>10*1024*1024||str_contains($s['name'],'..')||preg_match('/vbaProject|externalLinks|\.bin$/i',$s['name']))throw new \InvalidArgumentException('XLSX melebihi polisi import.');}
            $shared=[];if(($raw=$z->getFromName('xl/sharedStrings.xml'))!==false){$x=self::xml($raw);foreach($x->xpath('//*[local-name()="si"]') as $si){$text='';foreach($si->xpath('.//*[local-name()="t"]') as $t)$text.=(string)$t;if(mb_strlen($text)>2000||count($shared)>=20000)throw new \InvalidArgumentException('XLSX terlalu besar.');$shared[]=$text;}}
            $work=self::xml((string)$z->getFromName('xl/workbook.xml'));$sheets=$work->xpath('//*[local-name()="sheet"]');if(!$sheets)throw new \InvalidArgumentException('Worksheet tiada.');$rid=(string)$sheets[0]->attributes('http://schemas.openxmlformats.org/officeDocument/2006/relationships')['id'];$rels=self::xml((string)$z->getFromName('xl/_rels/workbook.xml.rels'));$target=null;foreach($rels->xpath('//*[local-name()="Relationship"]') as $rel)if((string)$rel['Id']===$rid){if((string)$rel['TargetMode']==='External')throw new \InvalidArgumentException('External link tidak dibenarkan.');$target=(string)$rel['Target'];}if(!$target||str_contains($target,'..')||str_contains($target,':'))throw new \InvalidArgumentException('Worksheet path tidak sah.');$name=str_starts_with($target,'/')?ltrim($target,'/'):'xl/'.$target;$xml=self::xml((string)$z->getFromName($name));$rows=[];foreach($xml->xpath('//*[local-name()="sheetData"]/*[local-name()="row"]') as $row){if(count($rows)>=1001)throw new \InvalidArgumentException('Maksimum 1000 staf.');$values=[];foreach($row->xpath('./*[local-name()="c"]') as $cell){if($cell->xpath('./*[local-name()="f"]'))throw new \InvalidArgumentException('Formula tidak dibenarkan.');if(!preg_match('/\A([A-Z]+)[0-9]+\z/',(string)$cell['r'],$m))throw new \InvalidArgumentException('Cell tidak sah.');$col=0;foreach(str_split($m[1]) as $ch)$col=$col*26+ord($ch)-64;$col--;if($col>=9)throw new \InvalidArgumentException('Maksimum 9 lajur.');$v=$cell->xpath('./*[local-name()="v"]');$value=(string)($v[0]??'');if((string)$cell['t']==='s'){if(!ctype_digit($value)||!isset($shared[(int)$value]))throw new \InvalidArgumentException('Shared string tidak sah.');$value=$shared[(int)$value];}elseif((string)$cell['t']==='inlineStr'){$value='';foreach($cell->xpath('.//*[local-name()="t"]') as $t)$value.=(string)$t;}if(mb_strlen($value)>2000)throw new \InvalidArgumentException('Cell terlalu panjang.');$values[$col]=$value;}if($values){$line=array_fill(0,max(array_keys($values))+1,'');foreach($values as $k=>$v)$line[$k]=$v;$rows[]=$line;}}return $rows;
        }finally{$z->close();}
    }
    public static function preview(\PDO $p,int $actor,array $rows):int {
        if(!Authorization::any($p,$actor,'core.registry.import'))throw new \RuntimeException('Akses tidak dibenarkan.');return Core::tx($p,function()use($p,$actor,$rows){Database::query($p,"INSERT INTO staff_import_batches(actor_id,expires_at) VALUES(?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 HOUR))",[$actor]);$batch=(int)$p->lastInsertId();$seen=[];foreach($rows as $i=>$d){try{Staff::validateRow($p,$actor,$d);$email=Core::email($d['official_email']??'');if(isset($seen[$email]))throw new \InvalidArgumentException('Duplicate e-mel dalam fail.');$seen[$email]=true;$result='VALID';}catch(\InvalidArgumentException|\RuntimeException $e){$result=$e instanceof \PDOException?'VALIDATION_FAILED':$e->getMessage();}Database::query($p,'INSERT INTO staff_import_items(batch_id,source_row,data_json,result) VALUES(?,?,?,?)',[$batch,$i+2,json_encode($d,JSON_THROW_ON_ERROR),$result]);}Audit::record($p,'registry.import_preview',$actor,null,(string)$batch);return $batch;});
    }
    public static function batch(\PDO $p,int $actor,int $id):array {$b=Database::query($p,'SELECT * FROM staff_import_batches WHERE id=? AND actor_id=? AND (expires_at>UTC_TIMESTAMP() OR status=\'COMMITTED\')',[$id,$actor])->fetch();if(!$b)throw new \RuntimeException('Preview tamat tempoh atau bukan milik anda.');return $b;}
    public static function commit(\PDO $p,int $actor,int $id):void {
        if(!Authorization::any($p,$actor,'core.registry.import'))throw new \RuntimeException('Akses tidak dibenarkan.');if((int)Database::query($p,'SELECT GET_LOCK(?,5)',['ep_import_'.$id])->fetchColumn()!==1)throw new \RuntimeException('Import sedang berjalan.');try{$b=self::batch($p,$actor,$id);if($b['status']!=='PREVIEW')throw new \RuntimeException('Import telah diproses.');$items=Database::query($p,'SELECT * FROM staff_import_items WHERE batch_id=? ORDER BY source_row',[$id])->fetchAll();foreach($items as $r){if($r['result']!=='VALID')continue;try{Core::tx($p,function()use($p,$actor,$r){$d=json_decode($r['data_json'],true,512,JSON_THROW_ON_ERROR);Authorization::require($p,$actor,'core.registry.import',Core::id($d['organisation_id']??''));$staff=Staff::preverify($p,$actor,$d);Database::query($p,"UPDATE staff_import_items SET result='IMPORTED',staff_identity_id=? WHERE id=?",[$staff,$r['id']]);});}catch(\Throwable $e){$msg=$e instanceof \InvalidArgumentException?$e->getMessage():'FAILED; scope/record changed or unavailable';Database::query($p,'UPDATE staff_import_items SET result=? WHERE id=?',[$msg,$r['id']]);}}Database::query($p,"UPDATE staff_import_batches SET status='COMMITTED' WHERE id=?",[$id]);Audit::record($p,'registry.import_committed',$actor,null,(string)$id);}finally{Database::query($p,'SELECT RELEASE_LOCK(?)',['ep_import_'.$id]);}
    }
}
